solution:
def count_readings(code: str) -> int:
    prev, cur = 0, 1                     # readings of code[:i - 1] and code[:i]; the empty prefix reads one way
    for i, d in enumerate(code):
        ways = cur if d != "0" else 0    # d read as a letter on its own
        if i > 0 and "10" <= code[i - 1:i + 1] <= "26":
            ways += prev                 # the last two digits read as one letter
        prev, cur = cur, ways
    return cur

perf.naive:
def count_readings(code: str) -> int:
    def ways(i):                         # readings of code[i:], recounted on every call
        if i == len(code):
            return 1
        if code[i] == "0":
            return 0
        total = ways(i + 1)
        if i + 1 < len(code) and int(code[i:i + 2]) <= 26:
            total += ways(i + 2)
        return total
    return ways(0)
